/*updateBuyerNoticeLCount*/

		UPDATE ICOMBOARD_NOTICE
		SET LCOUNT = NVL(LCOUNT, 0) + 1
		WHERE BID = #{BID}
		  AND BTYPE = #{BTYPE}

mapper.insert:
/*insertBuyerNoticeReadLog*/

		INSERT INTO ICOMBOARD_NOTICE_READ (BID, BTYPE, COM_CODE, USER_ID, READ_DATE)
		VALUES (#{bid}, #{btype}, #{comCode}, #{userId}, TO_CHAR(SYSDATE, 'YYYYMMDD'))

mapper.select:
/*selectBuyerNoticeReadCount*/

		SELECT COUNT(*) FROM ICOMBOARD_NOTICE_READ
		WHERE BID = #{bid} AND BTYPE = #{btype}
		  AND COM_CODE = #{comCode} AND USER_ID = #{userId}

mapper.insert:

INSERT INTO ICOMBOARD_NOTICE_DT (
	BID, BTYPE, COMPANY, STATUS, COM_CODE, COM_NAME, REG_DATE, REG_USER_ID
) VALUES (
	#{BID}, #{BTYPE}, #{COMPANY}, 'C', #{COM_CODE}, #{COM_NAME}, #{REG_DATE}, #{REG_USER_ID}
)

mapper.update:
/*deleteBuyerNotice*/

		UPDATE ICOMBOARD_NOTICE
		SET STATUS = 'D'
		WHERE BID = #{BID}
		  AND BTYPE = #{BTYPE}

mapper.select:
/*selectBuyerInquiryList - KEPAVCDT VOC 목록*/
SELECT A.VC_NO, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC03' AND CODE = A.CLAIM_MASTER) AS CLAIM_TEXT, A.CLAIM_MASTER, A.BUYER_ITEM_NO, A.PO_NO, A.REQ_REMARK, A.RECV_FLAG, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC02' AND CODE = A.RECV_FLAG) AS RECV_FLAG_TEXT, TO_CHAR(A.REQ_DATE,'YYYY.MM.DD') AS REQ_DATE_DIS, TO_CHAR(A.REQ_DATE,'YYYYMMDD') AS REQ_DATE, A.REQ_USER_ID, A.REQ_USER_NAME, A.REQ_USER_TEL, TO_CHAR(A.PH_DATE,'YYYY.MM.DD') AS PH_DATE_DIS, A.DS_REMARK_A, A.DF_REMARK, TO_CHAR(A.DF_DATE,'YYYY.MM.DD') AS DF_DATE_DIS, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.DS_USER_ID) AS DS_USER_NAME, A.CLAIM_TYPE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'VC01' AND CODE = A.CLAIM_TYPE) AS CLAIM_TYPE_TEXT, A.REQ_IMAGE_KEY, A.FEEDBACK_IMAGE_KEY, CASE WHEN A.RECV_FLAG = 'FB' AND (A.ANSWER_READ_DATE IS NULL OR A.ANSWER_READ_DATE < TO_CHAR(A.DF_DATE,'YYYYMMDD')) THEN 'N' ELSE 'Y' END AS READ_YN FROM KEPAVCDT A WHERE A.SYS_TYPE = 'KA' AND A.BUYER = #{st_company} AND A.REQ_USER_ID = #{st_user_id}
AND TO_CHAR(A.REQ_DATE,'YYYYMMDD') >= REPLACE(REPLACE(#{st_from_date}, '.', ''), '/', '')
AND TO_CHAR(A.REQ_DATE,'YYYYMMDD') <= REPLACE(REPLACE(#{st_to_date}, '.', ''), '/', '')
AND A.CLAIM_MASTER = #{st_claim_master}
AND A.RECV_FLAG IN ('DC', 'PS', 'PA')
AND A.RECV_FLAG = 'FB'
AND A.RECV_FLAG = #{st_recv_flag}
ORDER BY A.REQ_DATE DESC, A.VC_NO DESC

mapper.update:
/*cancelBuyerInquiry*/

		UPDATE KEPAVCDT
		SET RECV_FLAG = 'CX'
		WHERE VC_NO = #{st_vc_no}
		  AND BUYER = #{st_company}
		  AND RECV_FLAG = 'DC'

/*updateBuyerInquiryRead*/

		UPDATE KEPAVCDT
		   SET ANSWER_READ_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
		 WHERE VC_NO = #{st_vc_no}
		   AND BUYER = #{st_company}
		   AND REQ_USER_ID = #{st_user_id}
		   AND RECV_FLAG IN ('PA','FB')

mapper.select:
/*selectBuyerInternalNoticeList - 읽음 상태 포함 (ICOMBOARD_NOTICE_READ를 BTYPE='NTC'로 재사용)*/
SELECT A.BID, A.BTYPE, A.SUBJECT, A.CONTEXT, A.REG_USER_ID, A.REG_DATE, TO_CHAR(TO_DATE(A.REG_DATE,'YYYYMMDD'),'YYYY.MM.DD') AS REG_DATE_DIS, A.REG_TIME, A.IMAGE_KEY, A.LCOUNT, A.FROM_DATE, A.TO_DATE, TO_CHAR(TO_DATE(REPLACE(REPLACE(A.FROM_DATE,'/',''),'.',''),'YYYYMMDD'),'YYYY.MM.DD') AS FROM_DATE_DIS, TO_CHAR(TO_DATE(REPLACE(REPLACE(A.TO_DATE,'/',''),'.',''),'YYYYMMDD'),'YYYY.MM.DD') AS TO_DATE_DIS, A.OPEN_FLAG, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REG_USER_ID AND STATUS <> 'D') AS USER_NAME_LOC, CASE WHEN A.REG_DATE < '20260501' THEN 'Y' WHEN R.BID IS NOT NULL THEN 'Y' ELSE 'N' END AS READ_YN FROM BUYERBOARD A LEFT OUTER JOIN ICOMBOARD_NOTICE_READ R ON A.BID = R.BID AND R.BTYPE = 'NTC' AND R.COM_CODE = #{st_company} AND R.USER_ID = #{st_user_id} AND R.READ_DATE >= A.REG_DATE -- BID 재사용(삭제 후 재생성)으로 남은 등록일 이전의 옛 읽음로그는 무시 WHERE A.STATUS != 'D' AND A.BTYPE = 'NTC' AND A.BYCA_COMORG_CODE = #{st_byca_comorg_code}
AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN REPLACE(REPLACE(A.FROM_DATE,'/',''),'.','') AND REPLACE(REPLACE(A.TO_DATE,'/',''),'.','')
AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN REPLACE(REPLACE(A.FROM_DATE,'/',''),'.','') AND REPLACE(REPLACE(A.TO_DATE,'/',''),'.','')
AND (A.SUBJECT LIKE '%'||#{st_keyword}||'%' OR DBMS_LOB.INSTR(A.CONTEXT, #{st_keyword}) > 0)
ORDER BY A.BID DESC

mapper.update:
/*updateBuyerInternalNotice*/

	UPDATE BUYERBOARD
	   SET SUBJECT = #{SUBJECT},
	       CONTEXT = #{CONTEXT},
	       IMAGE_KEY = #{IMAGE_KEY},
	       FROM_DATE = REPLACE(REPLACE(#{FROM_DATE},'/',''),'.',''),
	       TO_DATE = REPLACE(REPLACE(#{TO_DATE},'/',''),'.','')
	 WHERE BID = #{BID}
	   AND BTYPE = 'NTC'
	   AND BYCA_COMORG_CODE = #{st_byca_comorg_code}

mapper.delete:
/*deleteBuyerInternalNotice*/

	DELETE FROM BUYERBOARD
	 WHERE BID = #{BID}
	   AND BTYPE = 'NTC'
	   AND BYCA_COMORG_CODE = #{st_byca_comorg_code}

mapper.update:
/*updateBuyerInternalNoticeLCount*/

	UPDATE BUYERBOARD
	   SET LCOUNT = LCOUNT + 1
	 WHERE BID = #{BID}
	   AND BTYPE = 'NTC'
	   AND BYCA_COMORG_CODE = #{st_byca_comorg_code}
	   AND STATUS <> 'D'

